# frozen_string_literal: true

require "rails_helper"

RSpec.describe Timekeeping::Alerts do
  # "`503 reference_unavailable` over 1% of writes for 5 minutes;"
  # The plan judges each company's latest completed window only; a window still in progress is never judged.
  it "a healthy write in a newer partial window neither hides a failed completed window nor fires on its own" do
    now = Time.utc(2026, 10, 26, 12, 7, 0)
    window = lambda do |start, writes, unavailable|
      { "window_start" => start.iso8601, "writes" => writes, "reference_unavailable" => unavailable,
        "latency_ms_sum" => 10 * (writes + unavailable),
        "latency_ms_buckets" => { "25" => writes + unavailable } }
    end
    metrics = lambda do |companies|
      { "window_seconds" => 300, "latency_bucket_bounds_ms" => [25, 50, 100, 200, 300, 500, 1000, 2500, 5000],
        "overflow_bucket" => "inf", "total_field" => "writes + reference_unavailable",
        "companies" => companies, "outbox_lag" => [] }
    end
    reference_alerts = lambda do |body|
      described_class.evaluate(now:, write_metrics: body)
                     .select { |alert| alert.name.to_s.include?("reference_unavailable") }
    end

    # Company 7: 3 of 50 failed in the completed 12:00-12:05 window, then one healthy write at 12:05.
    # Company 8: one failed write in the 12:05 window that is still in progress, nothing before it.
    # Company 9: writes 100 and reference_unavailable 1 is 1/101, under 1% once the denominator is
    # writes + reference_unavailable.
    body = metrics.call([
      { "company_id" => 7, "windows" => [window.call(Time.utc(2026, 10, 26, 12, 0), 47, 3),
                                         window.call(Time.utc(2026, 10, 26, 12, 5), 1, 0)] },
      { "company_id" => 8, "windows" => [window.call(Time.utc(2026, 10, 26, 12, 5), 0, 1)] },
      { "company_id" => 9, "windows" => [window.call(Time.utc(2026, 10, 26, 12, 0), 100, 1)] }
    ])

    expect(reference_alerts.call(body).map(&:company_id)).to eq([7])
  end
end

RSpec.describe Timekeeping::Alerts do
  # "Timekeeping p95 latency for entry writes over 300 ms."
  # Writes slower than the last bound are counted only under the body's overflow key, which is not in
  # latency_bucket_bounds_ms, so no finite bound ever reaches 95% for this company.
  it "raises the p95 latency alert when every write of a completed window lands in the overflow bucket" do
    now = Time.utc(2026, 10, 26, 12, 6, 0)
    body = {
      "window_seconds" => 300, "latency_bucket_bounds_ms" => [100, 300, 500], "overflow_bucket" => "beyond",
      "total_field" => "writes + reference_unavailable", "outbox_lag" => [],
      "companies" => [
        { "company_id" => 11, "windows" => [{ "window_start" => Time.utc(2026, 10, 26, 12, 0).iso8601,
                                               "writes" => 20, "reference_unavailable" => 0,
                                               "latency_ms_sum" => 20 * 6000,
                                               "latency_ms_buckets" => { "beyond" => 20 } }] },
        { "company_id" => 12, "windows" => [{ "window_start" => Time.utc(2026, 10, 26, 12, 0).iso8601,
                                               "writes" => 20, "reference_unavailable" => 0,
                                               "latency_ms_sum" => 20 * 250,
                                               "latency_ms_buckets" => { "300" => 20 } }] }
      ]
    }

    latency = described_class.evaluate(now:, write_metrics: body)
                             .select { |alert| alert.name.to_s.include?("latency") }

    expect(latency.map(&:company_id)).to eq([11])
  end
end
